128	  // A throwing repository must not fail the emit for sibling subscribers.
129	  it("isolates a write failure from the emitting service", async () => {
130	    vi.mocked(activityRepo.insertActivity).mockRejectedValueOnce(
131	      new Error("activity store unavailable"),
132	    );
133	
134	    const sibling = vi.fn();
